import numpy as np
from scipy.optimize import minimize


def min_max_dist_dim3_14() -> np.ndarray:
    """
    Approach: start from a parametric cube+octahedron construction (8 cube
    vertices at half-side s, 6 axis points at radius a), grid-tune (s, a)
    on the exact ratio dmin/dmax, then refine all 42 coordinates with a
    deterministic multistart L-BFGS-B local search on a smooth
    soft-min/soft-max surrogate. Incumbent selection uses the exact
    squared ratio (dmin/dmax)^2, and a finite (14,3) array is always
    returned.
    """
    n, d = 14, 3
    rng = np.random.RandomState(42)
    iu = np.triu_indices(n, 1)

    def ratio(P):
        D = np.sqrt(((P[:, None, :] - P[None, :, :]) ** 2).sum(-1))
        dd = D[iu]
        return dd.min() / dd.max()

    def cube_octa(s, a):
        P = np.zeros((n, d))
        k = 0
        for x in (-1, 1):
            for y in (-1, 1):
                for z in (-1, 1):
                    P[k] = (x * s, y * s, z * s)
                    k += 1
        for j in range(3):
            P[8 + 2 * j, j] = a
            P[9 + 2 * j, j] = -a
        return P

    # Grid-tune (s, a) on the exact ratio
    best_P = cube_octa(1.0, 1.0)
    best_r = ratio(best_P)
    for s in np.linspace(0.7, 1.4, 15):
        for a in np.linspace(0.7, 1.8, 23):
            P = cube_octa(s, a)
            r = ratio(P)
            if r > best_r:
                best_r, best_P = r, P

    # Smooth surrogate: minimize (softmax(d^2) - softmin(d^2)) / softmax(d^2)
    def soft_obj(x, p):
        P = x.reshape(n, d)
        D2 = ((P[:, None, :] - P[None, :, :]) ** 2).sum(-1)
        d2 = D2[iu]
        m = max(d2.max(), 0.0)
        z = p * (d2 - m)
        dmin_soft = m - np.log(np.exp(-z).sum()) / p
        dmax_soft = m + np.log(np.exp(z).sum()) / p
        return (dmax_soft - dmin_soft) / max(dmax_soft, 1e-12)

    def refine(x0, p, maxiter=3000):
        res = minimize(soft_obj, x0, args=(p,), method="L-BFGS-B",
                       options={"maxiter": maxiter})
        if not np.all(np.isfinite(res.x)):
            return None
        return res.x.reshape(n, d)

    def accept(P):
        nonlocal best_r, best_P
        if P is not None and np.all(np.isfinite(P)):
            r = ratio(P)
            if r > best_r:
                best_r, best_P = r, P

    # Diverse starts: perturbed incumbent at several radii + random configs
    starts = [best_P.ravel()]
    for rad in (0.03, 0.08, 0.15):
        for _ in range(4):
            starts.append((best_P + rad * rng.randn(n, d)).ravel())
    for _ in range(6):
        Q = rng.randn(n, d)
        Q -= Q.mean(0)
        starts.append(Q.ravel())

    # Stage 1: moderate sharpness from every start
    for x0 in starts:
        accept(refine(x0, 40.0))

    # Stage 2: anneal sharpness upward from the incumbent
    for p in (60.0, 100.0, 160.0, 250.0, 400.0):
        accept(refine(best_P.ravel(), p))

    return best_P


